  const activeStatuses=new Set(['created','submitting','submitted','generating','qa_running','rerolling']);
  function route(){const match=location.hash.match(/^#redraw\/([^/]+)\/stage\/(03|04)\/market\/(es-MX|pt-BR|en-US)$/i);if(!match)return null;const value={projectId:decodeURIComponent(match[1]),legacyStage:match[2]==='03',locale:match[3]};if(value.legacyStage)history.replaceState(null,'','#redraw/'+encodeURIComponent(value.projectId)+'/stage/04/market/'+value.locale);return value;}
