  function digestCanonical(value){return digest(canonical(value));}
  async function request(url,options={}){let nextOptions={...options};const step03Post=url.includes('/step03/')&&String(nextOptions.method||'GET').toUpperCase()==='POST',step05=url.includes('/step05/');if(step03Post||step05){if(!store.localizationRevision)throw Object.assign(new Error('请先确认当前地区改编稿'),{code:'LOCALIZATION_CONFIRMATION_REQUIRED'});const headers={...(nextOptions.headers||{}),'X-Localization-Revision':store.localizationRevision};let body=nextOptions.body;if(step03Post&&typeof body==='string'){const parsed=JSON.parse(body||'{}');body=JSON.stringify({...parsed,localization_revision:store.localizationRevision});}nextOptions={...nextOptions,headers,body};}const response=await fetch(url,{cache:'no-store',...nextOptions}),payload=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(payload.error||'请求失败');error.code=payload.code;error.status=response.status;error.items=payload.items;throw error;}return{payload,etag:response.headers.get('ETag'),localizationRevision:response.headers.get('X-Localization-Revision')};}
