  function statusLabel(status){return({planning:'规划中',character_review:'人物定稿',asset_generation:'资产生成',firstframe_generation:'镜头首帧',episode_review:'整集确认',awaiting_candidates:'等待候选',generating:'生产中',awaiting_confirmation:'待确认',confirmed:'已确认',awaiting_generation:'尚未生产',accepted:'已生成，等待确认',rejected:'质量检查未通过',rerolling:'重做中',blocked:'等待依赖',created:'已排队',submitting:'正在提交',submitted:'已提交',qa_running:'质量检查中',failed:'生产失败',needs_reroll:'需要重做',submission_uncertain:'正在核对已有任务'})[status]||status||'等待';}
