  function progress(){const p=store.plan?.progress||{};return '<div class="step03-progress"><span>风格 '+(p.style_confirmed?'已确认':'待确认')+'</span><span>人物 '+(p.important_characters_confirmed||0)+'/'+(p.important_characters_total||0)+'</span><span>资产 '+(p.assets_accepted||0)+'/'+(p.assets_total||0)+'</span><span>首帧 '+(p.groups_confirmed||0)+'/'+(p.groups_total||0)+'</span></div>';}
  function shell(body){const meta=locales[store.route.locale],steps=substeps.map(([id,label],index)=>'<button type="button" class="'+(store.substep===id?'is-active':'')+'" data-step03-substep="'+id+'"><span>0'+(index+1)+'</span><strong>'+label+'</strong></button>').join(''),resolutionOptions=[['1k','1K · 默认'],['2k','2K'],['4k','4K']].map(([value,label])=>'<option value="'+value+'" '+(store.generationResolution===value?'selected':'')+'>'+label+'</option>').join('');return '<section class="step03-stage"><header class="step03-header"><div class="step03-brand"><img src="./assets/brand/niannian-ai-fused-monogram-v6-brand-pink.png" alt=""><strong>念念AI</strong><i>/</i><span>资产与首帧 · '+escape(meta.label)+' · '+escape(meta.language)+'</span></div><label class="step03-generation-settings" title="只影响之后新建的图片任务，已有图片不会改变"><span>出图清晰度</span><select data-step03-resolution aria-label="出图清晰度">'+resolutionOptions+'</select><small>仅新任务</small></label><nav><button type="button" data-step03-back>地区改编</button><button type="button" data-step03-workbench>返回工作台</button></nav></header><div class="step03-substeps">'+steps+progress()+'</div>'+(store.error?'<aside class="step03-alert"><strong>操作未完成</strong><span>'+escape(store.error.message)+'</span><button type="button" data-step03-refresh>重新读取</button></aside>':'')+body+'</section>';}
  function empty(title,copy,action=''){return '<section class="step03-empty"><strong>'+escape(title)+'</strong><span>'+escape(copy)+'</span>'+action+'</section>';}
