    const notice=unconfirmed.length?'<aside class="step03-context-notice"><strong>需先确认 '+unconfirmed.length+' 位重要角色</strong><span>确认后才会开放依赖人物身份的资产生成。</span></aside>':'<aside class="step03-context-notice is-ready"><strong>人物身份已就绪</strong><span>只生成被生产分组真实引用的资产。</span></aside>';
