  function sanitizePublicText(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes)node.nodeValue=String(node.nodeValue||'').replace(/Step\s*0?1/gi,'原片分析').replace(/Step\s*0?2/gi,'原片时间轴').replace(/Step\s*0?3/gi,'资产与首帧').replace(/Step\s*0?4/gi,'地区改编').replace(/Step\s*0?5/gi,'资产与首帧').replace(/RunningHub|provider|receipt|controller|lease|token/gi,'生成服务').replace(/\b[a-f0-9]{32,64}\b/gi,'内部校验已隐藏');}
