  function prefetchCharacterArtifacts(){if(store.prefetchingArtifacts||navigator.connection?.saveData||/^(slow-2g|2g)$/.test(navigator.connection?.effectiveType||''))return;const queue=characterArtifactUrls().filter(url=>url&&!store.prefetchedArtifacts.has(url));if(!queue.length)return;store.prefetchingArtifacts=true;const next=()=>{const url=queue.shift();if(!url){store.prefetchingArtifacts=false;return;}const image=new Image();const done=()=>{store.prefetchedArtifacts.add(url);setTimeout(next,0);};image.addEventListener('load',done,{once:true});image.addEventListener('error',done,{once:true});image.src=url;};setTimeout(next,0);}
